create schema private;create schema auth;
create role anon;create role authenticated;
create table auth.users(id uuid primary key);
insert into auth.users select ('11111111-1111-4111-8111-'||lpad(n::text,12,'0'))::uuid from generate_series(1,4)n;
create table private.online_associations(association_id uuid primary key,name text,status text);
insert into private.online_associations values('22222222-2222-4222-8222-222222222222','수비길드','ACTIVE'),('33333333-3333-4333-8333-333333333333','공격길드','ACTIVE');
create table private.online_association_members(user_id uuid primary key,association_id uuid,role text);
insert into private.online_association_members select id,case when id::text like '%000000000001' or id::text like '%000000000002' then '22222222-2222-4222-8222-222222222222'::uuid else '33333333-3333-4333-8333-333333333333'::uuid end,case when id::text like '%000000000001' then 'LEADER' else 'MEMBER' end from auth.users;
create table private.village_life_towns(id text primary key);insert into private.village_life_towns values('city'),('herb-1');
create table private.village_life_players(user_id uuid primary key,products jsonb);
insert into private.village_life_players select id,'{"challenge_ticket":2}'::jsonb from auth.users;
create table private.village_war_declarations(cycle_key date,town_id text,association_id uuid,primary key(cycle_key,town_id,association_id));
insert into private.village_war_declarations values('2026-10-12','city','33333333-3333-4333-8333-333333333333'),('2026-10-12','herb-1','33333333-3333-4333-8333-333333333333');
create table public.game_player_profiles(user_id uuid primary key,nickname text);insert into public.game_player_profiles select id,'시험캐릭터' from auth.users;
create table public.game_saves(user_id uuid primary key,payload jsonb);
insert into public.game_saves select id,'{"equipped":{},"cosmetics":{},"nickname":"시험캐릭터"}'::jsonb from auth.users;
create table private.hunting_states(user_id uuid primary key,skills text[] default '{}',stat_allocation jsonb default '{}');insert into private.hunting_states(user_id) select id from auth.users;
create table private.market_assets(user_id uuid,item_id text,gear jsonb,quantity bigint);
create table private.learned_catalog_skills(user_id uuid,skill_id text,enhancement_level int);
create table private.player_association_seals(user_id uuid primary key,level int);
create function private.require_active_game_session(uuid,bigint,text,text) returns uuid language sql as $$select $1$$;
create function private.server_authoritative_payload(uuid,jsonb) returns jsonb language sql as $$select $2$$;
create function private.combat_equipment_stats(uuid,jsonb) returns jsonb language sql as $$select jsonb_build_object('hp',180+12*coalesce((stat_allocation->>'hp')::int,0),'attack',8,'defense',3) from private.hunting_states where user_id=$1$$;
create table private.war_test_marker(value text);insert into private.war_test_marker values('isolated-village-war-test');
